package com.dating.backend.admin;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.context.WebApplicationContext;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import jakarta.servlet.http.Cookie;import jakarta.persistence.EntityManager;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class AdminSecurityTest {
 @Autowired AdminService admins;@Autowired WebApplicationContext context;@Autowired EntityManager em;MockMvc mvc;AdminService.Login owner,reviewer,reader,support;
 @BeforeEach void setup(){mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();admins.create("owner","Owner-test-12345","OWNER");admins.create("reviewer","Reviewer-test-12345","REVIEWER");admins.create("reader","Reader-test-12345","READ_ONLY");admins.create("support","Support-test-12345","SUPPORT");owner=admins.login("owner","Owner-test-12345");reviewer=admins.login("reviewer","Reviewer-test-12345");reader=admins.login("reader","Reader-test-12345");support=admins.login("support","Support-test-12345");}
 Cookie cookie(AdminService.Login l){return new Cookie("dating_admin",l.token());}
 @Test void oldSharedKeyAndMissingSessionCannotAccessAdmin()throws Exception{mvc.perform(get("/api/admin/console/summary").header("X-Admin-Key","change-admin-review-key")).andExpect(status().isUnauthorized());mvc.perform(get("/api/admin/accounts")).andExpect(status().isUnauthorized());}
 @Test void ownerCanReadAccountsButHashNeverReturned()throws Exception{mvc.perform(get("/api/admin/accounts").cookie(cookie(owner))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("passwordHash"))));}
 @Test void csrfAndRoleBoundariesEnforcedAtApi()throws Exception{mvc.perform(post("/api/admin/accounts").cookie(cookie(owner)).contentType("application/json").content("{\"username\":\"new-admin\",\"password\":\"Long-password-123\",\"role\":\"READ_ONLY\"}")).andExpect(status().isForbidden());mvc.perform(get("/api/admin/accounts").cookie(cookie(reviewer))).andExpect(status().isForbidden());mvc.perform(post("/api/admin/reviews/1/approve").cookie(cookie(reader)).header("X-Admin-CSRF",reader.csrf()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(post("/api/admin/reviews/1/approve").cookie(cookie(support)).header("X-Admin-CSRF",support.csrf()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put("/api/admin/safety/users/1/review").cookie(cookie(reviewer)).header("X-Admin-CSRF",reviewer.csrf()).contentType("application/json").content("{}")).andExpect(status().isForbidden());}
 @Test void createAdminWorksAndAuditRecorded()throws Exception{mvc.perform(post("/api/admin/accounts").cookie(cookie(owner)).header("X-Admin-CSRF",owner.csrf()).contentType("application/json").content("{\"username\":\"new-admin\",\"password\":\"Long-password-123\",\"role\":\"READ_ONLY\"}")).andExpect(status().isOk());assertTrue(admins.accounts().stream().anyMatch(a->a.username().equals("new-admin")));assertTrue(admins.audits().stream().anyMatch(a->a.getAction().equals("POST /api/admin/accounts")));}
 @Test void disableRoleChangePasswordAndLogoutRevokeSessions(){admins.update(reviewer.account().id(),"READ_ONLY",true,null);assertNull(admins.authenticate(reviewer.token()));admins.update(reader.account().id(),"READ_ONLY",false,null);assertNull(admins.authenticate(reader.token()));admins.changePassword(admins.authenticate(owner.token()),"Owner-test-12345","Changed-owner-12345");assertNull(admins.authenticate(owner.token()));admins.logout(support.token());assertNull(admins.authenticate(support.token()));}
 @Test void lastOwnerCannotBeDisabledOrDemoted(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->admins.update(owner.account().id(),"READ_ONLY",true,null));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->admins.update(owner.account().id(),"OWNER",false,null));}
 @Test void lockoutAndExpiredSessions(){for(int i=0;i<5;i++)assertThrows(org.springframework.web.server.ResponseStatusException.class,()->admins.login("reader","wrong"));assertEquals(429,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->admins.login("reader","Reader-test-12345")).getStatusCode().value());em.find(AdminSession.class,AdminService.hash(owner.token())).setExpiresAt(java.time.Instant.now().minusSeconds(1));assertNull(admins.authenticate(owner.token()));}
 @Test void loginUsesHttpOnlyCookieAndNoTokenInBody()throws Exception{mvc.perform(post("/api/admin/session/login").contentType("application/json").content("{\"username\":\"owner\",\"password\":\"Owner-test-12345\"}")).andExpect(status().isOk()).andExpect(header().string("Set-Cookie",org.hamcrest.Matchers.containsString("HttpOnly"))).andExpect(header().string("Set-Cookie",org.hamcrest.Matchers.containsString("SameSite=Strict"))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("token"))));}
 @Test void permissionMatrix(){assertTrue(AdminFilter.allowed("REVIEWER","POST","/api/admin/reviews/1/approve"));assertTrue(AdminFilter.allowed("SUPPORT","PUT","/api/admin/safety/reports/1/resolve"));assertFalse(AdminFilter.allowed("SUPPORT","PUT","/api/admin/safety/blocked-identities/1/release"));assertFalse(AdminFilter.allowed("READ_ONLY","POST","/api/admin/future-endpoint"));}
}
